effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 p = (uv - vec2(centerX, centerY)) * vec2(ar, 1.0);
  float r = length(p);
  float t = clamp(r / max(radius, 1e-4), 0.0, 1.0);
  float f = 1.0 - amount * (1.0 - t * t) * mixAmt;
  vec2 q = p * f;
  uv = q / vec2(ar, 1.0) + vec2(centerX, centerY);
  gl_FragColor = texture2DCv(inputImg.texture, uv);
}
